class Solution {
  public int[] kthRemainingInteger(int[] nums, int[][] queries) {
    int n = nums.length;
    int[] evenCount = new int[n + 1];
    for (int i = 0; i < n; i++) evenCount[i + 1] = evenCount[i] + (nums[i] % 2 == 0 ? 1 : 0);
    int m = evenCount[n];
    long[] g = new long[m];
    int p = 0;
    for (int i = 0; i < n; i++) if (nums[i] % 2 == 0) g[p] = nums[i] / 2 - p++;
    int[] ans = new int[queries.length];
    for (int qi = 0; qi < queries.length; qi++) {
      int a = evenCount[queries[qi][0]], b = evenCount[queries[qi][1] + 1];
      long k = queries[qi][2];
      long threshold = k - a + 1;
      int lo = a, hi = b;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (g[mid] < threshold) lo = mid + 1;
        else hi = mid;
      }
      ans[qi] = (int) (2 * (k + (lo - a)));
    }
    return ans;
  }
}
